insert into public.articles (title, slug, excerpt, body, cover_image_url, category_id, author_id, kind, status, featured, tags, published_at)
values
  ('Why Does Michael Karnow Only Buy Socks From Uniqlo, and Only in Purple, Blue and Green?', 'why-does-michael-karnow-only-buy-socks-from-uniqlo-and-only-in-purple-blue-and-g', 'Three colours. One shop. No explanation. We spent six weeks trying to crack the case.', '<p>It began with a laundry basket. Inside: forty-one socks, every single one from Uniqlo, every single one purple, blue or green. Not a single grey. Not one black. Not even a navy, which, as one source pointed out, is basically blue that has given up.</p><p>We approached the subject directly. Michael Karnow looked at us for a long time, adjusted a purple ankle sock, and said only: “Red is for people who have something to prove.”</p><blockquote><p>Red is for people who have something to prove. Yellow is for people who have already lost.</p></blockquote><h2>The theories</h2><p>Theory one: he is colour-coding his week. Purple for Mondays, blue for the middle bit, green for “anything could happen”. Theory two: he once saw a peacock and never recovered. Theory three, put forward by a Uniqlo employee who asked not to be named: “He comes in, he touches every sock, he buys the same three. We have stopped asking.”</p><img src="https://picsum.photos/seed/byb2-inline-socks/1200/700" alt=""><p>When pressed on whether he would ever consider a sock from another shop, he left the room. We heard the drawer open. We heard it close. We believe he was checking they were still there.</p>', 'https://picsum.photos/seed/byb2-why-does-michael-karnow-only-buy-socks-f/1600/1000', (select id from public.categories where slug = 'ideas'), (select id from admin_user), 'magazine', 'published', true, array['michaelkarnow', 'socks', 'uniqlo', 'investigation', 'thebestof'], now() - interval '1 days 1 hours'),
  ('Michael Karnow''s Regimen for Staying Fit and Healthy', 'michael-karnow-s-regimen-for-staying-fit-and-healthy', 'A strict, scientifically unverified programme of wine, pool, yoga and three months in Georgia.', '<p>People often ask Michael Karnow how he stays in such remarkable shape. He is always happy to share his regimen, which he describes as “holistic, mostly liquid, and non-negotiable”.</p><h2>The programme</h2><ul><li><strong>Wine.</strong> Red on weekdays for the heart, white on weekends for the soul, orange in Georgia for cultural reasons.</li><li><strong>Pool.</strong> Not swimming. Billiards. “Leaning over the table is a core workout if you do it for six hours.”</li><li><strong>Yoga.</strong> One downward dog per day, held until someone notices.</li><li><strong>Living in Georgia for three months.</strong> “The mountains do the cardio for you. You just have to look at them.”</li><li><strong>Khachapuri.</strong> Classified as a protein shake.</li><li><strong>Purple, blue or green socks.</strong> See our previous investigation. He insists the circulation benefits are real.</li><li><strong>A nap at 15:00.</strong> Mandatory. Doctors have not been consulted.</li><li><strong>Dancing until sunrise once a quarter.</strong> “For the lymphatic system.”</li></ul><blockquote><p>If you''re not stretching while holding a glass of wine, you''re only doing half the stretch.</p></blockquote><p>We asked a personal trainer for comment. They read the list twice, laughed for an uncomfortable amount of time and then asked for his number.</p>', 'https://picsum.photos/seed/byb2-michael-karnow-s-regimen-for-staying-fit/1600/1000', (select id from public.categories where slug = 'ideas'), (select id from admin_user), 'magazine', 'published', true, array['michaelkarnow', 'fitness', 'wellness', 'georgia', 'wine'], now() - interval '3 days 2 hours'),
  ('Michael Karnow Has Opinions About Which Spoon Is the Correct Spoon', 'michael-karnow-has-opinions-about-which-spoon-is-the-correct-spoon', 'There are, according to him, exactly two acceptable spoons in any kitchen. The rest are “decorative cutlery”.', '<p>We visited a kitchen with Michael Karnow and watched him open the cutlery drawer the way a surgeon opens a patient. “This one,” he said, holding up a teaspoon. “And this one.” A soup spoon. The other eleven spoons were placed in a bag and given to a neighbour.</p><p>His reasoning is complex and changes depending on the soup.</p><blockquote><p>A spoon should feel like a handshake. Most spoons feel like an apology.</p></blockquote>', 'https://picsum.photos/seed/byb2-michael-karnow-has-opinions-about-which-/1600/1000', (select id from public.categories where slug = 'culture'), (select id from admin_user), 'magazine', 'published', false, array['michaelkarnow', 'kitchen', 'opinions'], now() - interval '5 days 3 hours'),
  ('Three Months in Georgia With Michael Karnow: A Survival Guide', 'three-months-in-georgia-with-michael-karnow-a-survival-guide', 'Bring stretchy trousers, a strong liver and at least four pairs of green socks.', '<p>Day one: he learned the Georgian word for “another”. Day four: he was invited to a supra, a feast with more toasts than there are hours in a day. Day eleven: a grandmother in Kakheti adopted him. Day ninety: he came home with a suitcase full of churchkhela and an accent nobody can place.</p><h2>What to pack</h2><p>Comfortable shoes for the mountains you will not climb. A notebook for the toasts you will forget. A spare pair of purple socks, because the first pair will be gifted to a shepherd in a moment of emotion.</p><img src="https://picsum.photos/seed/byb2-inline-georgia/1200/700" alt="">', 'https://picsum.photos/seed/byb2-three-months-in-georgia-with-michael-kar/1600/1000', (select id from public.categories where slug = 'travel'), (select id from admin_user), 'magazine', 'published', true, array['michaelkarnow', 'georgia', 'travel', 'wine', 'thebestof'], now() - interval '7 days 4 hours'),
  ('Warsaw Pigeon Forms Union, Demands Better Breadcrumbs', 'warsaw-pigeon-forms-union-demands-better-breadcrumbs', 'Negotiations with Plac Zbawiciela have stalled over the issue of sourdough.', '<p>A pigeon known locally as Zbigniew has unionised more than three hundred birds across Śródmieście. Their demands are simple: better bread, fewer scooters, and the right to sit on the statue''s head without being shooed.</p><p>Talks broke down on Tuesday when city officials offered rye. “Rye is an insult,” said a spokesbird, before flying directly into a window.</p>', 'https://picsum.photos/seed/byb2-warsaw-pigeon-forms-union-demands-better/1600/1000', (select id from public.categories where slug = 'culture'), (select id from admin_user), 'magazine', 'published', false, array['warsaw', 'pigeons', 'news', 'animals'], now() - interval '9 days 5 hours'),
  ('A Man Tried to Return a Pierogi to the Factory', 'a-man-tried-to-return-a-pierogi-to-the-factory', '“It was not the pierogi I was promised,” he said, holding a single dumpling in a sandwich bag.', '<p>He took two trams and a bus. He waited forty minutes at reception. He placed the pierogi on the desk and said, quietly, “This one has no potato in it.” Factory staff have since confirmed it was, in fact, a ravioli.</p>', 'https://picsum.photos/seed/byb2-a-man-tried-to-return-a-pierogi-to-the-f/1600/1000', (select id from public.categories where slug = 'culture'), (select id from admin_user), 'magazine', 'published', false, array['food', 'pierogi', 'warsaw', 'complaints'], now() - interval '11 days 6 hours'),
  ('Is Soup a Drink? A 4,000-Word Investigation', 'is-soup-a-drink-a-4-000-word-investigation', 'We asked chefs, philosophers and a man outside Żabka. Nobody came away unchanged.', '<p>If you drink it from a mug, is it still soup? If you eat it with a fork, are you okay? These are the questions that have kept our editorial team awake for eleven consecutive nights.</p><blockquote><p>Barszcz in a mug is a drink. Barszcz in a bowl is a lifestyle.</p></blockquote><p>The man outside Żabka was the most convincing. He said “soup is soup” and walked away, and frankly, he is right.</p>', 'https://picsum.photos/seed/byb2-is-soup-a-drink-a-4-000-word-investigati/1600/1000', (select id from public.categories where slug = 'ideas'), (select id from admin_user), 'magazine', 'published', false, array['food', 'soup', 'essay', 'philosophy'], now() - interval '13 days 7 hours'),
  ('Fashion Week Report: Wearing Two Coats at Once', 'fashion-week-report-wearing-two-coats-at-once', 'Why choose? This season''s most daring look is simply every coat you own.', '<p>Layering has gone too far, and we love it. On the runways of Mokotów, models walked in a trench over a puffer over a second, smaller trench. One model wore three and could not lower her arms. She won an award.</p>', 'https://picsum.photos/seed/byb2-fashion-week-report-wearing-two-coats-at/1600/1000', (select id from public.categories where slug = 'style'), (select id from admin_user), 'magazine', 'published', true, array['fashion', 'coats', 'trends', 'winter'], now() - interval '15 days 8 hours'),
  ('Ten Haircuts You Can Give Yourself at a Bus Stop', 'ten-haircuts-you-can-give-yourself-at-a-bus-stop', 'You have seven minutes until the 180 arrives. Let''s make them count.', '<p>Number one: the Express Fringe. Number four: the Pigeon, achieved with nail scissors and confidence. Number nine: the Missed My Bus, which is what happens when you attempt number eight.</p>', 'https://picsum.photos/seed/byb2-ten-haircuts-you-can-give-yourself-at-a-/1600/1000', (select id from public.categories where slug = 'style'), (select id from admin_user), 'magazine', 'published', false, array['hair', 'diy', 'warsaw', 'beauty'], now() - interval '17 days 9 hours'),
  ('Your Houseplant Is Judging You, and It Has Reasons', 'your-houseplant-is-judging-you-and-it-has-reasons', 'We interviewed a monstera about your watering habits. It did not hold back.', '<p>“Twice a week, they said. Twice. A. Week,” said the monstera, through a translator. It also had notes on the playlist, the lighting and the fact that you talk to the cactus more.</p>', 'https://picsum.photos/seed/byb2-your-houseplant-is-judging-you-and-it-ha/1600/1000', (select id from public.categories where slug = 'style'), (select id from admin_user), 'magazine', 'published', false, array['plants', 'home', 'design'], now() - interval '19 days 10 hours'),
  ('I Visited the Same Żabka Every Day for a Year', 'i-visited-the-same-zabka-every-day-for-a-year', 'Same shop, same hot dog, completely different person.', '<p>By month three, the cashier knew my name. By month six, she knew my secrets. By month twelve, I was invited to her wedding, where the catering was, naturally, from Żabka.</p>', 'https://picsum.photos/seed/byb2-i-visited-the-same-zabka-every-day-for-a/1600/1000', (select id from public.categories where slug = 'travel'), (select id from admin_user), 'magazine', 'published', false, array['warsaw', 'zabka', 'food', 'slowtravel'], now() - interval '21 days 11 hours'),
  ('The Best Benches in Łazienki, Ranked by a Professional Sitter', 'the-best-benches-in-lazienki-ranked-by-a-professional-sitter', 'After 214 benches and one peacock incident, we have a winner.', '<p>Our sitter, who has sat professionally since 2004, scored each bench on comfort, view and peacock exposure. Bench 87 was disqualified after a peacock sat on it first and refused to move.</p>', 'https://picsum.photos/seed/byb2-the-best-benches-in-lazienki-ranked-by-a/1600/1000', (select id from public.categories where slug = 'travel'), (select id from admin_user), 'magazine', 'published', false, array['warsaw', 'parks', 'thebestof', 'sitting'], now() - interval '23 days 12 hours'),
  ('Weekend Break: Inside an IKEA, Without Leaving, for Seven Days', 'weekend-break-inside-an-ikea-without-leaving-for-seven-days', 'I slept in nine bedrooms, ate 140 meatballs and was gently asked to leave by Thursday.', '<p>The trick is to keep moving. Showroom by day, rug department by night. On day five I met another man doing the same thing. We did not speak. We nodded. We knew.</p>', 'https://picsum.photos/seed/byb2-weekend-break-inside-an-ikea-without-lea/1600/1000', (select id from public.categories where slug = 'travel'), (select id from admin_user), 'magazine', 'published', false, array['ikea', 'travel', 'design', 'food'], now() - interval '25 days 13 hours'),
  ('What If Mondays Were Optional?', 'what-if-mondays-were-optional', 'An economist, a cat and Michael Karnow weigh in on the radical proposal.', '<p>The economist said productivity would rise. The cat said nothing and lay on the keyboard. Michael Karnow said he had not observed a Monday since 2019 and had never felt better, then went for a nap at 15:00 sharp.</p>', 'https://picsum.photos/seed/byb2-what-if-mondays-were-optional/1600/1000', (select id from public.categories where slug = 'ideas'), (select id from admin_user), 'magazine', 'published', false, array['essay', 'work', 'michaelkarnow'], now() - interval '27 days 14 hours'),
  ('Local Cat Elected to Mokotów District Council', 'local-cat-elected-to-mokotow-district-council', 'Her platform: more sunbeams, fewer vacuum cleaners, and a nap for every citizen.', '<p>Councillor Mruczka won by a landslide, mostly because she sat on the ballot box and nobody wanted to move her. Her first act in office was to knock a pen off the mayor''s desk.</p>', 'https://picsum.photos/seed/byb2-local-cat-elected-to-mokotow-district-co/1600/1000', (select id from public.categories where slug = 'culture'), (select id from admin_user), 'magazine', 'published', false, array['warsaw', 'cats', 'politics', 'news'], now() - interval '29 days 15 hours'),
  ('The Secret Society of People Who Clap When the Plane Lands', 'the-secret-society-of-people-who-clap-when-the-plane-lands', 'They meet at Chopin Airport. They clap at everything. We went undercover.', '<p>The initiation is simple: you clap when the plane lands. Then you clap when the bags arrive. Then you clap when the taxi arrives. Members clap at sunsets, toast and, on one occasion, a very good parking job.</p>', 'https://picsum.photos/seed/byb2-the-secret-society-of-people-who-clap-wh/1600/1000', (select id from public.categories where slug = 'culture'), (select id from admin_user), 'magazine', 'published', false, array['travel', 'planes', 'society', 'investigation'], now() - interval '31 days 16 hours'),
  ('Burn Yer Boats: Why We Set Fire to a Rowing Boat (Responsibly)', 'burn-yer-boats-why-we-set-fire-to-a-rowing-boat-responsibly', 'With the fire brigade''s permission, a bucket of water and a deep sense of commitment.', '<p>Every magazine needs a mission statement. Ours involved a second-hand rowing boat, a permit and a very patient firefighter named Tomek.</p><blockquote><p>You can''t go back to the shore if you''ve set fire to the boat. Also, please stand back.</p></blockquote><p>The boat burned for eleven minutes. Tomek put it out. We all felt deeply changed and slightly smoky.</p>', 'https://picsum.photos/seed/byb2-burn-yer-boats-why-we-set-fire-to-a-rowi/1600/1000', (select id from public.categories where slug = 'ideas'), (select id from admin_user), 'magazine', 'published', true, array['burnyerboats', 'essay', 'thebestof', 'commitment'], now() - interval '33 days 17 hours'),
  ('Michael Karnow Explains Why Every Playlist Needs Exactly One ABBA Song', 'michael-karnow-explains-why-every-playlist-needs-exactly-one-abba-song', 'Not zero. Not two. One. Placed strategically at track seven.', '<p>“Track seven is where the party either lives or dies,” he says. “ABBA at seven is a defibrillator.” He has rebuilt the playlists of eleven friends without asking.</p>', 'https://picsum.photos/seed/byb2-michael-karnow-explains-why-every-playli/1600/1000', (select id from public.categories where slug = 'ideas'), (select id from admin_user), 'magazine', 'published', false, array['michaelkarnow', 'music', 'abba', 'opinions'], now() - interval '35 days 18 hours'),
  ('My Neighbour Plays the Accordion at 6 A.M. and I''ve Started to Love It', 'my-neighbour-plays-the-accordion-at-6-a-m-and-i-ve-started-to-love-it', 'It began as a war. It became a duet.', '<p>At first I banged on the wall. Then I banged on the wall in rhythm. Now we perform together every morning and the whole building has a group chat about requests.</p>', 'https://picsum.photos/seed/byb2-my-neighbour-plays-the-accordion-at-6-a-/1600/1000', null, (select id from admin_user), 'member', 'published', false, array['warsaw', 'music', 'neighbours'], now() - interval '37 days 19 hours'),
  ('I Taught My Dog to Do My Taxes (He Refused)', 'i-taught-my-dog-to-do-my-taxes-he-refused', 'He''s good at fetching receipts. He''s terrible at deductions.', '<p>Week one: he ate the PIT-37. Week two: he filed nothing and lay on the calculator. Week three: we hired an accountant. The dog now supervises her.</p>', 'https://picsum.photos/seed/byb2-i-taught-my-dog-to-do-my-taxes-he-refuse/1600/1000', null, (select id from admin_user), 'member', 'published', false, array['dogs', 'money', 'life'], now() - interval '39 days 20 hours'),
  ('A Map of Every Café in Warsaw That Has Let Me Sit for Six Hours With One Coffee', 'a-map-of-every-caf-in-warsaw-that-has-let-me-sit-for-six-hours-with-one-coffee', 'A love letter to the heroes of hospitality, and an apology to the rest.', '<p>Café number one gave me a refill without asking. Café number nine pretended not to see me. Café number fourteen asked me to water the plants and I have worked there, unpaid, ever since.</p>', 'https://picsum.photos/seed/byb2-a-map-of-every-caf-in-warsaw-that-has-le/1600/1000', null, (select id from admin_user), 'member', 'published', true, array['coffee', 'warsaw', 'thebestof'], now() - interval '41 days 1 hours'),
  ('I Gave Up Sitting Down for Lent', 'i-gave-up-sitting-down-for-lent', 'Forty days. No chairs. Many leans.', '<p>I have leaned on walls, lampposts and, once, a stranger who did not mind. My legs are now stronger than my opinions.</p>', 'https://picsum.photos/seed/byb2-i-gave-up-sitting-down-for-lent/1600/1000', null, (select id from admin_user), 'member', 'published', false, array['life', 'challenges', 'fitness'], now() - interval '43 days 2 hours'),
  ('My Grandmother''s Recipe Box Contains Only Instructions for Pierogi and Revenge', 'my-grandmother-s-recipe-box-contains-only-instructions-for-pierogi-and-revenge', 'Card 12 is just the word “vinegar” underlined three times.', '<p>Most cards are pierogi. Some are not. One simply says “for Halina, after the wedding” and lists twelve cloves of garlic. We do not talk about Halina.</p>', 'https://picsum.photos/seed/byb2-my-grandmother-s-recipe-box-contains-onl/1600/1000', null, (select id from admin_user), 'member', 'published', false, array['food', 'family', 'pierogi', 'recipes'], now() - interval '45 days 3 hours'),
  ('The Allotment Wars: My Courgette Is Bigger Than Yours', 'the-allotment-wars-my-courgette-is-bigger-than-yours', 'Spring brings seeds, slugs and a feud with Mr Wiśniewski that will outlive us both.', '<p>He measured his courgette with a tape measure. I measured mine with a ruler from 1987. The judges were his cousins. I am appealing.</p>', 'https://picsum.photos/seed/byb2-the-allotment-wars-my-courgette-is-bigge/1600/1000', null, (select id from admin_user), 'member', 'published', false, array['gardening', 'community', 'rivalry'], now() - interval '47 days 4 hours'),
  ('Meet Ponchki, the Cyborg Pug Who Runs on Treats and Pure Spite', 'meet-ponchki-the-cyborg-pug-who-runs-on-treats-and-pure-spite', 'Half pug, half machine, entirely unbothered. An exclusive interview with Warsaw''s most advanced dog.', '<p>Ponchki was an ordinary pug until 2024, when a series of increasingly ambitious vet visits left him with a titanium left paw, a laser in one eye and a firmware update that only installs when someone opens a packet of ham.</p><p>He does not fetch. He calculates. When you throw a ball, Ponchki tracks its trajectory, estimates the effort required to retrieve it, and lies down. “Inefficient,” his collar says, in a calm robotic voice.</p><h2>A day in the life</h2><ul><li><strong>06:00</strong> — Boot sequence. Snores at 70 decibels.</li><li><strong>07:30</strong> — Scans the kitchen for crumbs using thermal vision.</li><li><strong>11:00</strong> — Downloads the neighbour''s Wi-Fi password. Uses it to order more treats.</li><li><strong>15:00</strong> — Joins Michael Karnow for his mandatory nap. They have a professional understanding.</li><li><strong>23:00</strong> — Patrols the flat. Barks at a plastic bag. Logs the incident.</li></ul><blockquote><p>I am not a good boy. I am an optimised boy.</p></blockquote><p>Asked whether he has any plans for world domination, Ponchki blinked his red eye twice, sneezed, and fell asleep mid-sentence. Experts say this is either a system error or the most pug thing that has ever happened.</p><img src="https://picsum.photos/seed/byb2-inline-ponchki/1200/700" alt="">', 'https://picsum.photos/seed/byb2-meet-ponchki-the-cyborg-pug-who-runs-on-/1600/1000', (select id from public.categories where slug = 'culture'), (select id from admin_user), 'magazine', 'published', true, array['ponchki', 'pugs', 'cyborg', 'warsaw', 'thebestof'], now() - interval '0 hours'),
  ('I Quit My Job to Watch Paint Dry, and I Found Myself in the Paint', 'i-quit-my-job-to-watch-paint-dry-and-i-found-myself-in-the-paint', 'Forty-one days. One wall. Three coats of eggshell white. This is the story of how I stopped running and started drying.', '<p>It started on a Tuesday, the way all great collapses do. I was in a meeting about a meeting, watching a slide titled “Synergy Roadmap Q3 (v14 FINAL final)”, when I realised I had not felt anything since 2019. That evening I handed in my notice, drove to a DIY shop, and bought one tin of eggshell white and a folding chair.</p><h2>Day one: the first coat</h2><p>I painted the wall in my spare room. It took forty minutes. Then I sat down. The paint glistened. It was wet in a way that felt almost arrogant, as if it knew it had all the time in the world. I watched it for six hours. Nothing happened. And then — and I need you to understand how big this was — slightly less nothing happened.</p><h2>Day four: the doubts</h2><p>My mother called. “Are you watching paint dry?” she asked. “Yes,” I said. There was a long pause, the kind you only hear in families. “Is it drying?” she asked eventually. And I realised I didn''t know. Drying is not an event. Drying is a relationship.</p><blockquote><p>You can''t rush paint. Paint is the only honest thing left.</p></blockquote><h2>Day nine: the second coat</h2><p>I added a second coat to see if the paint and I could start again. We could. I noticed things I had never noticed before: the way the light shifts across a wall at 16:12, the tiny ridges a roller leaves behind like fingerprints, the faint smell that is half chemical and half new beginning. I began keeping a journal. Entry 37 simply reads: “Still tacky. Same.”</p><img src="https://picsum.photos/seed/byb2-inline-paint/1200/700" alt=""><h2>Day nineteen: the breakthrough</h2><p>Somewhere around hour 300, I stopped watching the paint and the paint started watching me. In the soft sheen of eggshell white I saw my reflection: tired, unshaven, wearing the same jumper for a week. And behind it, very faintly, I saw someone I hadn''t seen in years. Someone who used to be patient. Someone who used to wait for things.</p><p>I cried. The paint did not. It was, by then, touch-dry.</p><h2>Day forty-one: dry</h2><p>On the final day I pressed one finger gently against the wall. Nothing came away. It was finished. I was finished. Or perhaps — and this is what the wall taught me — I was finally just beginning to dry.</p><p>I now run a weekend retreat called Drying Together. Attendees bring their own folding chair. We paint one wall and sit with it in silence. Last month a banker from Mokotów stood up on day two and shouted “I''m in the paint!” and nobody laughed, because we all knew exactly what he meant.</p><blockquote><p>Some people find themselves in the mountains. I found myself in a wall in my spare room. It''s closer, and there''s parking.</p></blockquote>', 'https://picsum.photos/seed/byb2-i-quit-my-job-to-watch-paint-dry-and-i-f/1600/1000', (select id from public.categories where slug = 'ideas'), (select id from admin_user), 'magazine', 'published', true, array['paint', 'life', 'slowliving', 'essay', 'thebestof'], now() - interval '1 hours')
